```python
import os
import re
import uuid
import shutil
import subprocess
from pathlib import Path
from typing import Callable, Optional

import modal


VOLUME_NAME = "media-storage"
MOUNT_PATH = "/vol"
APP_NAME = "crystal-clear-audio"

CLEANER_DSP = """declare name "cleaner";
declare description "Faust mono restoration chain (transient protection, HP/LP, gate, compression, makeup) [page:0]";
import("stdfaust.lib");

onepole(alpha) = ( *(1.0 - alpha) , *(alpha) ) : + ~ _;
tau_to_alpha(tau) = exp(-1.0 / (SR * max(tau, 1.0 / SR)));

tp_tau = hslider("transientProtectMs", 0.5, 0.0, 5.0, 0.01) * 0.001;
transientProtect = onepole(tau_to_alpha(tp_tau));

hp = fi.highpass(2, 80);
lp = fi.lowpass(2, 15000);

env_tau = hslider("gateEnvMs", 3.0, 0.1, 50.0, 0.1) * 0.001;
envFollower = abs : onepole(tau_to_alpha(env_tau));

gate_thresh_db = hslider("gateThresholdDb", -20.0, -80.0, 0.0, 0.1);
gate_thresh_lin = ba.db2linear(gate_thresh_db);

gate_tau = hslider("gateSmoothingMs", 5.0, 0.1, 50.0, 0.1) * 0.001;
gateGain = (envFollower > gate_thresh_lin) : onepole(tau_to_alpha(gate_tau));

compress_ratio = hslider("compressRatio", 4.0, 1.0, 20.0, 0.1);
compress_thresh_db = hslider("compressThreshDb", -18.0, -60.0, 0.0, 0.1);
compress_att = hslider("compressAttackMs", 10.0, 0.1, 200.0, 0.1) * 0.001;
compress_rel = hslider("compressReleaseMs", 200.0, 1.0, 2000.0, 1.0) * 0.001;
compressor = co.compressor_mono(compress_ratio, compress_thresh_db, compress_att, compress_rel);

makeup_db = hslider("makeupDb", 6.0, -12.0, 24.0, 0.1);
makeup = ba.db2linear(makeup_db);

process = _ : transientProtect : hp : lp : *(gateGain) : compressor : *(makeup);
"""


def _sanitize_filename(name: str) -> str:
    name = name or "input.mp4"
    name = name.strip().replace("\x00", "")
    name = re.sub(r"[^\w.\-]+", "_", name)
    if not name.lower().endswith((".mp4", ".mov", ".mkv", ".webm", ".m4v", ".avi")):
        name = f"{name}.mp4"
    return name[:255]


def _run(cmd: list[str], cwd: Optional[str] = None) -> None:
    p = subprocess.run(
        cmd,
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    if p.returncode != 0:
        raise RuntimeError(
            "Command failed",
            {
                "cmd": cmd,
                "cwd": cwd,
                "returncode": p.returncode,
                "stdout": p.stdout[-20000:],
                "stderr": p.stderr[-20000:],
            },
        )


volume = modal.Volume.from_name(VOLUME_NAME, create_if_missing=True)

image = (
    modal.Image.debian_slim(python_version="3.11")
    .apt_install(
        "ffmpeg",
        "faust",
        "g++",
        "make",
        "pkg-config",
        "libsndfile1",
        "libsndfile1-dev",
        "ca-certificates",
    )
    .pip_install(
        "fastapi==0.115.6",
        "python-multipart==0.0.20",
        "uvicorn==0.32.1",
    )
)

app = modal.App(APP_NAME, image=image)


@app.function(
    gpu="B200:1",
    volumes={MOUNT_PATH: volume},
    cpu=8,
    memory=32768,
    timeout=60 * 30,
)
def process_video(file_bytes: bytes, original_filename: str) -> bytes:
    if not isinstance(file_bytes, (bytes, bytearray)) or len(file_bytes) == 0:
        raise ValueError("Empty upload")

    safe_name = _sanitize_filename(original_filename)
    job_id = uuid.uuid4().hex
    job_dir = Path(MOUNT_PATH) / "jobs" / job_id
    job_dir.mkdir(parents=True, exist_ok=True)

    input_video = job_dir / safe_name
    dsp_path = job_dir / "cleaner.dsp"
    extracted_wav = job_dir / "extracted.wav"
    processed_wav = job_dir / "processed.wav"
    output_mp4 = job_dir / "output.mp4"

    input_video.write_bytes(bytes(file_bytes))
    dsp_path.write_text(CLEANER_DSP, encoding="utf-8")

    _run(
        [
            "ffmpeg",
            "-hide_banner",
            "-loglevel",
            "error",
            "-y",
            "-i",
            str(input_video),
            "-vn",
            "-map",
            "0:a:0",
            "-ac",
            "1",
            "-c:a",
            "pcm_s16le",
            "-f",
            "wav",
            str(extracted_wav),
        ],
        cwd=str(job_dir),
    )

    _run(
        [
            "faust2sndfile",
            "-double",
            "-vec",
            "-vs",
            "64",
            "-O",
            str(dsp_path),
        ],
        cwd=str(job_dir),
    )

    produced_bin = job_dir / "cleaner"
    if not produced_bin.exists():
        candidates = [p for p in job_dir.iterdir() if p.is_file() and os.access(p, os.X_OK)]
        raise RuntimeError("faust2sndfile did not produce expected binary", {"candidates": [c.name for c in candidates]})

    _run(
        [
            str(produced_bin),
            "-i",
            str(extracted_wav),
            "-o",
            str(processed_wav),
        ],
        cwd=str(job_dir),
    )

    if not processed_wav.exists() or processed_wav.stat().st_size == 0:
        raise RuntimeError("Processed WAV missing or empty")

    _run(
        [
            "ffmpeg",
            "-hide_banner",
            "-loglevel",
            "error",
            "-y",
            "-i",
            str(input_video),
            "-i",
            str(processed_wav),
            "-map",
            "0:v:0",
            "-map",
            "1:a:0",
            "-c:v",
            "copy",
            "-c:a",
            "aac",
            "-b:a",
            "192k",
            "-movflags",
            "+faststart",
            "-shortest",
            str(output_mp4),
        ],
        cwd=str(job_dir),
    )

    out = output_mp4.read_bytes()
    try:
        shutil.rmtree(job_dir, ignore_errors=True)
    finally:
        volume.commit()

    return out


@app.function(volumes={MOUNT_PATH: volume}, timeout=60 * 30)
@modal.asgi_app()
def web() -> Callable:
    from fastapi import FastAPI, File, UploadFile, HTTPException
    from fastapi.responses import Response

    api = FastAPI(title="crystal-clear-audio [web:15][web:37]")

    @api.post("/clean")
    async def clean(file: UploadFile = File(...)) -> Response:
        if file is None:
            raise HTTPException(status_code=400, detail="No file provided")
        data = await file.read()
        if not data:
            raise HTTPException(status_code=400, detail="Empty file")
        filename = file.filename or "input.mp4"
        try:
            result = process_video.remote(data, filename)
        except Exception as e:
            raise HTTPException(status_code=500, detail=str(e))
        return Response(content=result, media_type="video/mp4")

    return api
