import React, { useMemo, useState } from "react";

const API_URL = import.meta.env.VITE_API_URL;

export default function App() {
  const [file, setFile] = useState(null);
  const [busy, setBusy] = useState(false);
  const [resultUrl, setResultUrl] = useState(null);
  const [error, setError] = useState(null);

  const canStart = useMemo(() => !!file && !busy, [file, busy]);

  const onPick = (e) => {
    setError(null);
    setResultUrl((prev) => {
      if (prev) URL.revokeObjectURL(prev);
      return null;
    });
    const f = e.target.files && e.target.files[0] ? e.target.files[0] : null;
    setFile(f);
  };

  const start = async () => {
    setError(null);
    if (!API_URL) {
      setError("Missing VITE_API_URL");
      return;
    }
    if (!file) {
      setError("No file selected");
      return;
    }

    setBusy(true);
    setResultUrl((prev) => {
      if (prev) URL.revokeObjectURL(prev);
      return null;
    });

    try {
      const form = new FormData();
      form.append("file", file, file.name);

      const url = new URL("/clean", API_URL).toString();
      const res = await fetch(url, { method: "POST", body: form });

      if (!res.ok) {
        const txt = await res.text().catch(() => "");
        throw new Error(txt || `HTTP ${res.status}`);
      }

      const blob = await res.blob();
      if (!blob || blob.size === 0) throw new Error("Empty response");
      const objUrl = URL.createObjectURL(blob);
      setResultUrl(objUrl);
    } catch (e) {
      setError(e && e.message ? e.message : String(e));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 flex items-start justify-center p-6">
      <div className="w-full max-w-2xl bg-white border border-gray-200 rounded-lg p-6 shadow-sm">
        <h1 className="text-xl font-semibold tracking-tight">Crystal-clear audio</h1>
        <p className="text-sm text-gray-600 mt-2">
          Upload a video and receive a restored version with cleaned mono audio.
        </p>

        <div className="mt-6">
          <label className="block text-sm font-medium text-gray-800">Video file</label>
          <input
            type="file"
            accept="video/*"
            onChange={onPick}
            disabled={busy}
            className="mt-2 block w-full text-sm text-gray-700 file:mr-4 file:py-2 file:px-3 file:rounded-md file:border-0 file:bg-gray-100 file:text-gray-900 hover:file:bg-gray-200 disabled:opacity-60"
          />
          {file ? (
            <div className="mt-2 text-xs text-gray-600">
              Selected: <span className="font-medium text-gray-800">{file.name}</span>
            </div>
          ) : null}
        </div>

        <div className="mt-6 flex items-center gap-3">
          <button
            onClick={start}
            disabled={!canStart}
            className="px-4 py-2 rounded-md bg-gray-900 text-white text-sm font-medium disabled:bg-gray-300 disabled:text-gray-600"
          >
            {busy ? "Processing..." : "Upload / Start"}
          </button>
          <div className="text-xs text-gray-600">
            {busy ? "This can take a few minutes depending on video length." : null}
          </div>
        </div>

        {error ? (
          <div className="mt-6 rounded-md border border-red-200 bg-red-50 p-3 text-sm text-red-800">
            {error}
          </div>
        ) : null}

        {resultUrl ? (
          <div className="mt-8">
            <div className="text-sm font-medium text-gray-800">Result</div>
            <video className="mt-3 w-full rounded-md border border-gray-200" controls src={resultUrl} />

              Download cleaned MP4

          </div>
        ) : null}
      </div>
    </div>
  );
}
